                  style={{
                    backgroundColor: isCompleted ? habitColor : isFuture ? undefined : '#E5E7EB',
                  }}
                  title={date}
                  aria-label={`${date}${isCompleted ? ' (completed)' : ''}`}
                />
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}
